const started = $('Brief').first().json.started_at;
const finished = new Date().toISOString();
const duration_s = Math.round((new Date(finished).getTime() - new Date(started).getTime()) / 1000);
return [{ json: {
  run_id: $('Brief').first().json.run_id,
  workflow: 'WF1-brand-strategist',
  batch_id: '',
  started_at: started,
  finished_at: finished,
  duration_s: String(duration_s),
  llm_cost_usd: '',
  posts_count: '',
  cost_per_post_usd: '',
  notes: 'brand constitution v1 generated'
}}];
